// Generated by vibes-espmatter – commissionable Matter device: node, setup code and factory reset.
//
// The setup code comes from the build configuration (MESP_MATTER_PASSCODE / _DISCRIMINATOR), not
// the well-known test code 20202021. The Spake2+ verifier for it is computed on the device the
// first time a controller pairs. The device attests with esp-matter's test certificates (vendor
// 0xFFF1): controllers show it as an uncertified device.
#include "espm_node.h"
#include "espm_config.h"

#include <cstring>
#include <driver/gpio.h>
#include <esp_log.h>
#include <esp_mac.h>
#include <freertos/FreeRTOS.h>
#include <freertos/task.h>

#include <esp_matter_providers.h>

#include <setup_payload/OnboardingCodesUtil.h>
#include <app/server/Server.h>
#include <crypto/CHIPCryptoPAL.h>
#include <platform/CommissionableDataProvider.h>

static const char *TAG = "mesp_node";

using namespace esp_matter;

#define MAX_CALLBACKS 4
/** Hold the reset button this long to forget all pairings (factory reset). */
#define RESET_HOLD_MS 10000

static node_t *s_node;
static mesp_node_attribute_cb_t s_callbacks[MAX_CALLBACKS];
static size_t s_callback_count;

namespace {

/** Setup code from the build config; the verifier is derived from it on first use. */
class ConfigCommissionableDataProvider : public chip::DeviceLayer::CommissionableDataProvider {
public:
    CHIP_ERROR GetSetupDiscriminator(uint16_t &out) override
    {
        out = MESP_MATTER_DISCRIMINATOR;
        return CHIP_NO_ERROR;
    }
    CHIP_ERROR SetSetupDiscriminator(uint16_t) override { return CHIP_ERROR_NOT_IMPLEMENTED; }

    CHIP_ERROR GetSpake2pIterationCount(uint32_t &out) override
    {
        out = chip::Crypto::kSpake2p_Min_PBKDF_Iterations;
        return CHIP_NO_ERROR;
    }

    CHIP_ERROR GetSpake2pSalt(chip::MutableByteSpan &buf) override
    {
        init_salt();
        return chip::CopySpanToMutableSpan(chip::ByteSpan(m_salt), buf);
    }

    CHIP_ERROR GetSpake2pVerifier(chip::MutableByteSpan &buf, size_t &out_len) override
    {
        if (!m_have_verifier) {
            init_salt();
            chip::Crypto::Spake2pVerifier verifier;
            ReturnErrorOnFailure(verifier.Generate(chip::Crypto::kSpake2p_Min_PBKDF_Iterations,
                                                   chip::ByteSpan(m_salt), MESP_MATTER_PASSCODE));
            chip::MutableByteSpan span(m_verifier);
            ReturnErrorOnFailure(verifier.Serialize(span));
            m_have_verifier = true;
        }
        out_len = sizeof(m_verifier);
        return chip::CopySpanToMutableSpan(chip::ByteSpan(m_verifier), buf);
    }

    CHIP_ERROR GetSetupPasscode(uint32_t &out) override
    {
        out = MESP_MATTER_PASSCODE;
        return CHIP_NO_ERROR;
    }
    CHIP_ERROR SetSetupPasscode(uint32_t) override { return CHIP_ERROR_NOT_IMPLEMENTED; }

private:
    /** Fixed prefix + the chip's MAC: stable per device, different between devices. */
    void init_salt()
    {
        if (m_have_salt) return;
        static const char prefix[] = "vibes-espmatter-SPAKE2P"; // 22 bytes, without the NUL
        memcpy(m_salt, prefix, sizeof(prefix) - 1);
        esp_efuse_mac_get_default(m_salt + sizeof(prefix) - 1);
        m_have_salt = true;
    }

    uint8_t m_salt[22 + 6];
    uint8_t m_verifier[chip::Crypto::kSpake2p_VerifierSerialized_Length];
    bool m_have_salt = false;
    bool m_have_verifier = false;
};

ConfigCommissionableDataProvider s_provider;

} // namespace

static esp_err_t on_attribute(attribute::callback_type_t type, uint16_t endpoint_id, uint32_t cluster_id,
                              uint32_t attribute_id, esp_matter_attr_val_t *val, void *)
{
    for (size_t i = 0; i < s_callback_count; i++) {
        esp_err_t err = s_callbacks[i](type, endpoint_id, cluster_id, attribute_id, val);
        if (err != ESP_OK) return err;
    }
    return ESP_OK;
}

static esp_err_t on_identify(identification::callback_type_t type, uint16_t endpoint_id, uint8_t effect_id,
                             uint8_t effect_variant, void *)
{
    ESP_LOGI(TAG, "Identify %s on endpoint %u", type == identification::START ? "start" : "stop", endpoint_id);
    return ESP_OK;
}

void mesp_node_init()
{
    node::config_t config;
    strlcpy(config.root_node.basic_information.node_label, MESP_DEVICE_NAME,
            sizeof(config.root_node.basic_information.node_label));
    s_node = node::create(&config, on_attribute, on_identify);
    if (!s_node) {
        ESP_LOGE(TAG, "Failed to create the Matter node");
        return;
    }
    set_custom_commissionable_data_provider(&s_provider);
}

node_t *mesp_node()
{
    return s_node;
}

void mesp_node_add_attribute_callback(mesp_node_attribute_cb_t cb)
{
    if (s_callback_count < MAX_CALLBACKS) s_callbacks[s_callback_count++] = cb;
}

#if MESP_MATTER_RESET_GPIO >= 0
static void reset_button_task(void *)
{
    gpio_config_t io = {};
    io.pin_bit_mask = 1ULL << MESP_MATTER_RESET_GPIO;
    io.mode = GPIO_MODE_INPUT;
    io.pull_up_en = GPIO_PULLUP_ENABLE;
    gpio_config(&io);
    uint32_t held_ms = 0;
    while (true) {
        vTaskDelay(pdMS_TO_TICKS(100));
        held_ms = gpio_get_level((gpio_num_t)MESP_MATTER_RESET_GPIO) == 0 ? held_ms + 100 : 0;
        if (held_ms == 3000) ESP_LOGW(TAG, "Keep holding the button for a factory reset");
        if (held_ms >= RESET_HOLD_MS) {
            ESP_LOGW(TAG, "Factory reset: forgetting all pairings");
            factory_reset(); // reboots
            held_ms = 0;
        }
    }
}
#endif

void mesp_node_start()
{
    {
        lock::ScopedChipStackLock lock(portMAX_DELAY);
        size_t fabrics = chip::Server::GetInstance().GetFabricTable().FabricCount();
        ESP_LOGI(TAG, "Paired with %u controller(s). Setup code for pairing:", (unsigned)fabrics);
        PrintOnboardingCodes(chip::RendezvousInformationFlags(chip::RendezvousInformationFlag::kBLE));
    }
#if MESP_MATTER_RESET_GPIO >= 0
    xTaskCreate(reset_button_task, "mesp_reset", 2560, nullptr, 2, nullptr);
#endif
}
